COURSE.glossary.push(
  ["discriminative model", R`A model that only learns to tell classes apart, $p(y \mid x)$. It cannot create new data.`, ["discriminative"]],
  ["generative model", R`A model that learns what the data itself looks like, $p(x)$, so it can create new examples.`, ["generative", "generative models"]],
  ["decision boundary", R`The dividing line (or surface) a classifier draws between classes.`],
  ["conditional generation", R`Generating something that fits a given condition $c$, like a prompt or a class: sampling from $p(x \mid c)$.`],
  ["maximum likelihood", R`Training a model so the real training data becomes as likely as possible under the model.`],
  ["anomaly detection", R`Spotting unusual inputs: things the model thinks are very unlikely.`],
  ["data augmentation", R`Making extra training examples by flipping, rotating, cropping or adding noise to existing ones.`],
  ["oversampling", R`Repeating or blending examples of a rare class so it appears more often in training.`],
  ["Bernoulli", R`The distribution of a single yes/no outcome with probability $p$ of “yes”.`],
  ["categorical distribution", R`A distribution over several categories, one probability each, adding up to 1. Softmax produces one.`, ["Categorical"]],
  ["activation function", R`The bend applied after a neuron's weighted sum, like ReLU or sigmoid. Without it, many layers act like one.`, ["activation", "activations", "activation functions"]],
  ["sigmoid", R`$\sigma(z) = \frac{1}{1+e^{-z}}$: squashes any number into $(0, 1)$.`],
  ["ReLU", R`$\max(0, z)$: passes positives unchanged and turns negatives into 0. The default hidden-layer activation.`],
  ["softmax", R`Turns a list of scores into probabilities that are positive and add to 1: $\frac{e^{z_k}}{\sum_j e^{z_j}}$.`],
  ["logits", R`The raw scores a network outputs before softmax turns them into probabilities.`, ["logit"]],
  ["loss", R`One number measuring how wrong the model is. Training tries to make it small.`, ["loss function", "losses"]],
  ["MSE", R`Mean squared error: the average of $(\text{true} - \text{predicted})^2$. Used for real-valued outputs.`, ["mean squared error"]],
  ["cross-entropy", R`A loss for probabilities: $-\log$ of the probability the model gave to the right answer.`, ["binary cross-entropy", "BCE", "categorical cross-entropy"]],
  ["one-hot", R`A label written as a list of 0s with a single 1 at the correct class, e.g. $[0, 1, 0]$.`],
  ["vanishing gradient", R`When gradients shrink to almost zero on the way back through many layers, so early layers stop learning.`, ["vanishing gradients"]],
  ["optimizer", R`The rule that updates the weights using the gradient, e.g. SGD, Adam.`, ["optimizers"]],
  ["epoch", R`One full pass through the whole training dataset.`, ["epochs"]],
  ["batch", R`A small group of training examples used together for one update.`, ["mini-batch", "batch size"]],
  ["SGD", R`Stochastic gradient descent: update the weights using the slope measured on one example or a small batch.`, ["stochastic gradient descent"]],
  ["momentum", R`Stepping with a moving average of recent slopes instead of only the newest, which smooths out zig-zags.`],
  ["EWMA", R`Exponentially weighted moving average: a running average where newer values count more.`, ["exponentially weighted moving average"]],
  ["Adam", R`A popular optimizer combining momentum with per-weight step sizes (RMSProp) and bias correction.`],
  ["RMSProp", R`An optimizer that divides each step by the root of a moving average of squared slopes.`],
  ["AdaGrad", R`An optimizer that divides each step by the root of the total of all past squared slopes; its steps eventually shrink to zero.`],
  ["CNN", R`Convolutional neural network: a network that slides small filters over images.`, ["CNNs", "convolutional neural network"]],
  ["convolution", R`Sliding a small grid of weights over an image, multiplying and adding at each spot.`, ["convolutions"]],
  ["kernel", R`The small grid of learnable weights a convolution slides over the image. Also called a filter.`, ["filter", "filters", "kernels"]],
  ["feature map", R`The grid of outputs produced by sliding one filter over an image.`, ["feature maps"]],
  ["padding", R`A border of zeros added around an image so the filter can reach the edges.`],
  ["stride", R`How many pixels the filter jumps each time it moves.`],
  ["pooling", R`Shrinking a feature map by keeping the max (or average) of each small window. It has no parameters.`, ["max pooling", "average pooling"]],
  ["flatten", R`Unrolling a block of numbers into one long list.`],
  ["dense layer", R`A layer where every input connects to every neuron. Also called fully connected.`, ["dense", "fully connected"]],
  ["overfitting", R`Memorising the training data instead of learning general patterns, so the model does badly on new data.`],
  ["dropout", R`Randomly switching off some neurons during training so the network does not rely too much on any one.`],
  ["transfer learning", R`Reusing a network trained on a big dataset and retraining only its last part for your task.`],
  ["ensemble", R`Several models combined (by voting or averaging) to make one better prediction.`, ["ensembles"]],
  ["semantic segmentation", R`Labelling every pixel with a class, without separating individual objects.`],
  ["instance segmentation", R`Labelling every pixel and also separating individual objects of the same class.`]
);
